import torch
import torch.nn as nn
from torch.utils.cpp_extension import load_inline

# Define the custom CUDA kernel for cumulative product
cumprod_source = """
#include <torch/extension.h>
#include <cuda_runtime.h>

__global__ void cumprod_kernel(const float* input, float* output, int dim_size, int stride, int total_elements) {
    int idx = blockIdx.x * blockDim.x + threadIdx.x;
    if (idx < total_elements) {
        int dim_idx = idx / stride % dim_size;
        int base_idx = idx - dim_idx * stride;
        float prod = 1.0f;
        for (int i = 0; i <= dim_idx; ++i) {
            prod *= input[base_idx + i * stride];
        }
        output[idx] = prod;
    }
}

torch::Tensor cumprod_cuda(torch::Tensor input, int dim) {
    auto input_shape = input.sizes();
    auto output = torch::zeros_like(input);
    int dim_size = input_shape[dim];
    int stride = 1;
    for (int i = dim + 1; i < input_shape.size(); ++i) {
        stride *= input_shape[i];
    }
    int total_elements = input.numel();

    const int block_size = 256;
    const int num_blocks = (total_elements + block_size - 1) / block_size;

    cumprod_kernel<<<num_blocks, block_size>>>(input.data_ptr<float>(), output.data_ptr<float>(), dim_size, stride, total_elements);

    return output;
}
"""

cumprod_cpp_source = (
    "torch::Tensor cumprod_cuda(torch::Tensor input, int dim);"
)

# Compile the inline CUDA code for cumulative product
cumprod = load_inline(
    name="cumprod",
    cpp_sources=cumprod_cpp_source,
    cuda_sources=cumprod_source,
    functions=["cumprod_cuda"],
    verbose=True,
    extra_cflags=[""],
    extra_ldflags=[""],
)


class ModelNew(nn.Module):
    """
    A model that performs a cumulative product operation along a specified dimension using a custom CUDA kernel.

    Parameters:
        dim (int): The dimension along which to perform the cumulative product operation.
    """

    def __init__(self, dim):
        """
        Initialize the CumulativeProductModel.

        Args:
            dim (int): The dimension along which to perform the cumulative product.
        """
        super(ModelNew, self).__init__()
        self.dim = dim
        self.cumprod = cumprod

    def forward(self, x):
        """
        Forward pass, computing the cumulative product along the specified dimension using a custom CUDA kernel.

        Args:
            x (torch.Tensor): Input tensor of shape (batch_size, *input_shape).

        Returns:
            torch.Tensor: Tensor of the same shape as `x` after applying cumulative product along `dim`.
        """
        return self.cumprod.cumprod_cuda(x, self.dim)
